//	DE-1108
//	 new partner 
//***************************************
{
var camera = new Camera(VIDEO_CAMERA_TYPE.NETWORK, "DE-1108", 8, 0, 0, 1, 0, 0);
{
var codec = new CodecInfo(CODEC_TYPE.CODEC_H264, "H264", VIDEO_FORMAT_TYPE.FORMAT_NTSC);
codec.addResolution(new ResolutionInfo(RESOLUTION_TYPE.RES_360_240, "360x240", 30));
codec.addResolution(new ResolutionInfo(RESOLUTION_TYPE.RES_640_360, "640x360", 30));
codec.addResolution(new ResolutionInfo(RESOLUTION_TYPE.RES_720_480, "720x480", 30));
codec.addResolution(new ResolutionInfo(RESOLUTION_TYPE.RES_960_480, "960x480", 30));

codec.addQuality(new QualityInfo(QUALITY_TYPE.QUALITY_BASIC, "Basic"));
codec.addQuality(new QualityInfo(QUALITY_TYPE.QUALITY_STANDARD, "Standard"));
codec.addQuality(new QualityInfo(QUALITY_TYPE.QUALITY_HIGH, "High"));
codec.addQuality(new QualityInfo(QUALITY_TYPE.QUALITY_VERY_HIGH, "Very High"));

codec.support_framerate = [1,2,3,4,5,10,15,30];
camera.addCodec(codec);
}
camera.init(false);
// profiles는 개별 profile struct의 array이다. 각 profile의 current를 변경하면
// 해당 사항이 function이 끝난후 UI에 자동 반영된다.
camera.setAdjustFunction(
function func(profiles)
{
//Not Need Adjust
}
);
// camera는 현재 bitrate를 알고자 하는 카메라이다. 해당 오브젝트 내부정보를 가지고
// 각 Profile의 current setting에 따라 current_bitrate를 계산해서 넣은뒤 반환해 주면 된다.
camera.setCalculateFunction(
function func(camera)
{
	var maxStreamCount = 1;
	var codecFactor = 1.066000;
	var resolutionFactor = [1, 2.66, 4, 4];
	var resolutionBias = [10, 9, 8, 8, 2];
	var qualityIncreseRate = [1, 2, 3, 4];

	for (profile_index in camera.current_profiles) {
		var profile = camera.current_profiles[profile_index];
		var codecInfo = camera.getCodecInfo(profile.current_codec);
		var resolution = profile.current_resolution;
		var quality = profile.current_quality;
		var framerate = profile.current_framerate;
		var maxFramerate = codecInfo.getResolutionInfo(resolution).max_framerate;

		var resolutionFactorIndex = -1;
		var resolutionBiasIndex = -1;
		var resolutionQualityIndex = -1;
/*
		for (x in codecInfo.support_resolution) {
            if (codecInfo.support_resolution[x].type== resolution) {				
			    resolutionFactorIndex = resolutionBiasIndex = x;
				break;
            }
		}
		
		for (x in codecInfo.support_quality) {
            if (codecInfo.support_quality[x].type== quality) {				
			    resolutionQualityIndex = x;
				break;
            }
		}
*/
        switch (resolution) {
    		case RESOLUTION_TYPE.RES_360_240: resolutionFactorIndex = resolutionBiasIndex = 0; break;
    		case RESOLUTION_TYPE.RES_640_360: resolutionFactorIndex = resolutionBiasIndex = 1; break;
    		case RESOLUTION_TYPE.RES_720_480: resolutionFactorIndex = resolutionBiasIndex = 2; break;
    		case RESOLUTION_TYPE.RES_960_480: resolutionFactorIndex = resolutionBiasIndex = 3; break;
    	}
    	switch (quality) {
    		case QUALITY_TYPE.QUALITY_LOW: 		resolutionQualityIndex = 0; break;
    		case QUALITY_TYPE.QUALITY_BASIC: 		resolutionQualityIndex = 0; break;
    		case QUALITY_TYPE.QUALITY_STANDARD: 	resolutionQualityIndex = 1; break;
    		case QUALITY_TYPE.QUALITY_HIGH: 			resolutionQualityIndex = 2; break;
    		case QUALITY_TYPE.QUALITY_VERY_HIGH: 	resolutionQualityIndex = 3; break;
	    }

		var cbr = codecFactor * resolutionFactor[resolutionFactorIndex] * qualityIncreseRate[resolutionQualityIndex] * 8;
		var framerate_scale = Math.round(Math.sqrt(framerate) * 10, 0);
		var framerate_scale_30 = Math.round(Math.sqrt(maxFramerate) * 10, 1);
		var bitrateFactor = (framerate_scale + resolutionBias[resolutionBiasIndex]) / (framerate_scale_30 + resolutionBias[resolutionBiasIndex]);

		//console.log("[DE-110x] cbr = " + cbr + ", bitrate_factor = " + bitrateFactor + ", maxFramerate = " + maxFramerate);
		//console.log("[DE-110x] framerate_scale = " + framerate_scale + ", framerate_scale_30 = " + framerate_scale_30 + ", framerate = " + framerate);

	    profile.current_bitrate = cbr * bitrateFactor * maxFramerate;
		console.log("[DE-110x] profile.current_bitrate = " + profile.current_bitrate);		
	}
}
);
g_camera_models.push(camera);
}

