// cameras는 현재 connect된 camera list이다. 해당 카메라들의 정보를 가지고,
// 현재 video recoder에서 설정가능한 설정 상태인지를 확인하고 수정한다.
// 수정된 카메라의 정보는 UI로 바로 업데이트 된다.
vr.setAdjustCameras(
function func(camera)
{
    var resolution_list = [];
    var maxResolution = [];
    var maxPixel = 0;
    //recorder
    var resolutions = g_current_video_recoder_model.support_resolution_types;
    var res_max = resolutions.length-1;
    
    resolution_list = camera.support_codecs[0].support_resolution;
    
    maxResolution = resolution_list[0].name.split('x');
    maxPixel = Math.round(maxResolution[0] * maxResolution[1] / 1000000);
    switch(maxPixel) {
		case 0:
			if (resolution_list[0].name == "704x480" )  {
				for(var profileIndex = 0; profileIndex < 6; profileIndex++) {
					document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[0].text = RESOLUTION_TYPE_STRING[resolutions[0]]  + "(360x240)";
					document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[1].text = RESOLUTION_TYPE_STRING[resolutions[1]]  + "(720x240)";
					document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[2].text = RESOLUTION_TYPE_STRING[resolutions[2]]  + "(720x480)";
				}
			}
			else if (resolution_list[0].name == "960x480") {
				for(var profileIndex = 0; profileIndex < 6; profileIndex++) {
					document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[0].text = RESOLUTION_TYPE_STRING[resolutions[0]]  + "(480x240)";
					document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[1].text = RESOLUTION_TYPE_STRING[resolutions[1]]  + "(960x240)";
					document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[2].text = RESOLUTION_TYPE_STRING[resolutions[2]]  + "(960x480)";
				}
			}
			break;
		case 1:
			for(var profileIndex = 0; profileIndex < 6; profileIndex++) {
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[0].text = RESOLUTION_TYPE_STRING[resolutions[0]]  + "(360x240)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[1].text = RESOLUTION_TYPE_STRING[resolutions[1]]  + "(720x480)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[2].text = RESOLUTION_TYPE_STRING[resolutions[2]]  + "(1280x720)";
			}
			break;
		case 2:
			for(var profileIndex = 0; profileIndex < 6; profileIndex++) {
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[0].text = RESOLUTION_TYPE_STRING[resolutions[0]]  + "(720x480)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[1].text = RESOLUTION_TYPE_STRING[resolutions[1]]  + "(1280x720)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[2].text = RESOLUTION_TYPE_STRING[resolutions[2]]  + "(1920x1080)";
			}
			break;	
		case 3:
			for(var profileIndex = 0; profileIndex < 6; profileIndex++) {
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[0].text = RESOLUTION_TYPE_STRING[resolutions[0]]  + "(720x480)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[1].text = RESOLUTION_TYPE_STRING[resolutions[1]]  + "(1280x720)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[2].text = RESOLUTION_TYPE_STRING[resolutions[2]]  + "(1920x1536)";
			}
			break;
		case 4:
			for(var profileIndex = 0; profileIndex < 6; profileIndex++) {
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[0].text = RESOLUTION_TYPE_STRING[resolutions[0]]  + "(720x480)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[1].text = RESOLUTION_TYPE_STRING[resolutions[1]]  + "(1280x720)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[2].text = RESOLUTION_TYPE_STRING[resolutions[2]]  + "(2560x1440)";
			}
			break;
		case 5:
			for(var profileIndex = 0; profileIndex < 6; profileIndex++) {
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[0].text = RESOLUTION_TYPE_STRING[resolutions[0]]  + "(720x480)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[1].text = RESOLUTION_TYPE_STRING[resolutions[1]]  + "(1920x1080)";
				document.getElementById("select_" + STREAM_CONTROL_NAMES[profileIndex] + "_resolution").options[2].text = RESOLUTION_TYPE_STRING[resolutions[2]]  + "(2560x1920)";
			}
			break;
         default:
            break;
    }
	for (var codecIndex = 0; codecIndex < camera.support_codecs.length; codecIndex++) {
		camera.support_codecs[codecIndex].support_framerate = [1, 2, 3, 4, 5, 10, 15, 30];
	}
}
);

// 현재 선택된 current camera의 profile setting을 현재 video recoder에 
// 맞도록 셋팅한다.
vr.setAdjustDefaultSettings(
function func(camera)
{
//최초 카메라 선택시 Default로 보여줄 설정값 세팅

//STREAM_LIVE1 = 0;
//STREAM_LIVE2 = 1;
//STREAM_RECORD_TIMELAPS = 2;
//STREAM_RECORD_EVENT = 3;
//STREAM_REMOTE = 4;
var camera_list = document.getElementById("select_camera_model");
var resolution_list = [];
var maxResolution = [];
var maxPixel = 0;

selectOption = "";

for (var index = 0; index < camera_list.length; index++) {
    resolution_list = g_camera_models[camera_list[index].value].support_codecs[0].support_resolution;
    maxResolution = resolution_list[0].name.split('x');
    maxPixel = Math.round(maxResolution[0] * maxResolution[1] / 1000000);
    if (maxPixel > 2) {
        camera_list.removeChild(camera_list[index--]);
    }
}
    resolution_list = camera.support_codecs[0].support_resolution;
    camera.support_codecs[0].support_resolution.push(resolution_list[0]);
    camera.support_codecs[0].support_resolution.push(resolution_list[0]);
    camera.support_codecs[0].support_resolution.push(resolution_list[0]);
    
    var resolutions = g_current_video_recoder_model.support_resolution_types;
    var res_max = resolutions.length-1;
    
    camera.current_profiles[STREAM_LIVE1].current_framerate = 30;
    camera.current_profiles[STREAM_LIVE2].current_framerate = 15;
    camera.current_profiles[STREAM_REMOTE].current_framerate = 5;
    camera.current_profiles[STREAM_RECORD_TIMELAPS].current_framerate = 30;
    camera.current_profiles[STREAM_RECORD_EVENT].current_framerate = 30;
    
    camera.current_profiles[STREAM_LIVE1].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
    camera.current_profiles[STREAM_LIVE2].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
    camera.current_profiles[STREAM_REMOTE].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
    camera.current_profiles[STREAM_RECORD_TIMELAPS].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
    camera.current_profiles[STREAM_RECORD_EVENT].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
    
    //live1, recording은 최대 resolution, liv2는 최소, remote는 최소
    camera.current_profiles[STREAM_LIVE1].current_resolution = resolutions[res_max];
    camera.current_profiles[STREAM_LIVE2].current_resolution = resolutions[0];
    camera.current_profiles[STREAM_REMOTE].current_resolution = resolutions[0];
    camera.current_profiles[STREAM_RECORD_TIMELAPS].current_resolution = resolutions[res_max];
    camera.current_profiles[STREAM_RECORD_EVENT].current_resolution = resolutions[res_max];
}
);

// videoRecoder는  현재 선택된 recoder오브젝트이다. 해당 카메라 내부의 Profile로 부터
// 개별 birate를 읽어 현재 videorecoder의 current_record_bitrate를 계산한다.
vr.setCalculateBitrate(
function func(videoRecoder)
{
	var real_bitrate = [
    // D1
	[
		[   // Resolution Standard
            [0.06, 0.09, 0.11, 0.14, 0.17, 0.21, 0.25, 0.51], // Quality Low
            [0.10, 0.14, 0.17, 0.21, 0.25, 0.32, 0.38, 0.76], // Quality Standard
            [0.16, 0.23, 0.29, 0.35, 0.42, 0.53, 0.64, 1.28], // Quality High
            [0.20, 0.28, 0.35, 0.42, 0.51, 0.64, 0.76, 1.53]  // Quality Very High
        ],
        [   // Resolution High
            [0.13, 0.18, 0.23, 0.28, 0.34, 0.42, 0.51, 1.02], // Quality Low
            [0.20, 0.28, 0.35, 0.42, 0.51, 0.64, 0.76, 1.53], // Quality Standard
            [0.34, 0.46, 0.59, 0.71, 0.85, 1.06, 1.28, 2.56], // Quality High
            [0.40, 0.56, 0.71, 0.85, 1.02, 1.28, 1.53, 3.07]  // Quality Very High
        ],
        [   // Resolution Very High
            [0.27, 0.37, 0.47, 0.57, 0.68, 0.85, 1.02, 2.04], // Quality Low
            [0.40, 0.56, 0.71, 0.85, 1.02, 1.28, 1.53, 3.07], // Quality Standard
            [0.68, 0.93, 1.19, 1.43, 1.70, 2.13, 2.56, 5.12], // Quality High
            [0.81, 1.12, 1.43, 1.71, 2.04, 2.56, 3.07, 6.14]  // Quality Very High
        ]
    ],

    // HD
    [
        [   // Resolution Standard
            [0.06, 0.09, 0.11, 0.14, 0.17, 0.21, 0.25, 0.51], // Quality Low
            [0.10, 0.14, 0.17, 0.21, 0.25, 0.32, 0.38, 0.76], // Quality Standard
            [0.16, 0.23, 0.29, 0.35, 0.42, 0.53, 0.64, 1.28], // Quality High
            [0.20, 0.28, 0.35, 0.42, 0.51, 0.64, 0.76, 1.53]  // Quality Very High
        ],
        [   // Resolution High
            [0.27, 0.37, 0.47, 0.57, 0.68, 0.85, 1.02, 2.04], // Quality Low
            [0.40, 0.56, 0.71, 0.85, 1.02, 1.28, 1.53, 3.07], // Quality Standard
            [0.68, 0.93, 1.19, 1.43, 1.70, 2.13, 2.56, 5.12], // Quality High
            [0.81, 1.12, 1.43, 1.71, 2.04, 2.56, 3.07, 6.14]  // Quality Very High
        ],
        [   // Resolution Very High
            [0.27, 0.37, 0.47, 0.57, 0.68, 0.85, 1.02, 2.04], // Quality Low
            [0.47, 0.65, 0.83, 1.00, 1.19, 1.49, 1.79, 3.58], // Quality Standard
            [0.74, 1.03, 1.31, 1.57, 1.87, 2.34, 2.81, 5.63], // Quality High
            [0.95, 1.31, 1.66, 2.00, 2.38, 2.98, 3.58, 7.16]  // Quality Very High
        ]
    ],

    // 960H
	[
		[   // Resolution Standard
            [0.06, 0.09, 0.11, 0.14, 0.17, 0.21, 0.25, 0.51], // Quality Low
            [0.10, 0.14, 0.17, 0.21, 0.25, 0.32, 0.38, 0.76], // Quality Standard
            [0.16, 0.23, 0.29, 0.35, 0.42, 0.53, 0.64, 1.28], // Quality High
            [0.20, 0.28, 0.35, 0.42, 0.51, 0.64, 0.76, 1.53]  // Quality Very High
        ],
        [   // Resolution High
            [0.13, 0.18, 0.23, 0.28, 0.34, 0.42, 0.51, 1.02], // Quality Low
            [0.20, 0.28, 0.35, 0.42, 0.51, 0.64, 0.76, 1.53], // Quality Standard
            [0.34, 0.46, 0.59, 0.71, 0.85, 1.06, 1.28, 2.56], // Quality High
            [0.40, 0.56, 0.71, 0.85, 1.02, 1.28, 1.53, 3.07]  // Quality Very High
        ],
        [   // Resolution Very High
            [0.27, 0.37, 0.47, 0.57, 0.68, 0.85, 1.02, 2.04], // Quality Low
            [0.40, 0.56, 0.71, 0.85, 1.02, 1.28, 1.53, 3.07], // Quality Standard
            [0.68, 0.93, 1.19, 1.43, 1.70, 2.13, 2.56, 5.12], // Quality High
            [0.81, 1.12, 1.43, 1.71, 2.04, 2.56, 3.07, 6.14]  // Quality Very High
        ]
    ],

    // FullHD
    [
        [    // Resolution Standard
            [0.27, 0.37, 0.47, 0.57, 0.68, 0.85, 1.02, 2.04], // Quality Low
            [0.40, 0.56, 0.71, 0.85, 1.02, 1.28, 1.53, 3.07], // Quality Standard
            [0.68, 0.93, 1.19, 1.43, 1.70, 2.13, 2.56, 5.12], // Quality High
            [0.81, 1.12, 1.43, 1.71, 2.04, 2.56, 3.07, 6.14]  // Quality Very High        
        ],
        [    // Resolution High
            [0.27, 0.37, 0.47, 0.57, 0.68, 0.85, 1.02, 2.04], // Quality Low
            [0.47, 0.65, 0.83, 1.00, 1.19, 1.49, 1.79, 3.58], // Quality Standard
            [0.74, 1.03, 1.31, 1.57, 1.87, 2.34, 2.81, 5.63], // Quality High
            [0.95, 1.31, 1.66, 2.00, 2.38, 2.98, 3.58, 7.16]  // Quality Very High       
        ],
        [    // Resolution Very High
            [0.54, 0.75, 0.95, 1.14, 1.36, 1.70, 2.04, 4.09], // Quality Low
            [0.68, 0.93, 1.19, 1.43, 1.70, 2.13, 2.56, 5.12], // Quality Standard
            [0.81, 1.12, 1.43, 1.71, 2.04, 2.56, 3.07, 6.14], // Quality High
            [1.09, 1.50, 1.90, 2.29, 2.73, 3.41, 4.09, 8.19]  // Quality Very High        
        ]
    ]
];
	
	var bitrate = 0;
	for (camera_index in videoRecoder.connect_cameras) {
		var camera = videoRecoder.connect_cameras[camera_index];
		for (profile_index in camera.current_profiles) {
			var profile = camera.current_profiles[profile_index];
			var res_camera = camera.support_codecs[0].support_resolution[0].type;
			var res_nvr = parseInt(profile.current_resolution);
			var quality = parseInt(profile.current_quality);
			var codecInfo = camera.getCodecInfo(profile.current_codec);
			var framerate = parseInt(profile.current_framerate);
			var is_pal = (codecInfo.format == VIDEO_FORMAT_TYPE.FORMAT_PAL);
			var pal_increse_rate = 1.2;
			
			var res_cam_idx, resIdx, qulIdx;
			switch (res_camera) {
				case RESOLUTION_TYPE.RES_704_480: res_cam_idx = 0; break;
				case RESOLUTION_TYPE.RES_640_480: res_cam_idx = 0; break;
				case RESOLUTION_TYPE.RES_1280_720: res_cam_idx = 1; break;
				case RESOLUTION_TYPE.RES_960_480: res_cam_idx = 2; break;
				case RESOLUTION_TYPE.RES_1920_1080: res_cam_idx = 3; break;
			}
			
			switch (res_nvr) {
				case RESOLUTION_TYPE.RES_STANDARD: resIdx = 0; break;
				case RESOLUTION_TYPE.RES_HIGH: resIdx = 1; break;
				case RESOLUTION_TYPE.RES_VERY_HIGH: resIdx = 2; break;
			}
			switch (quality) {
				case QUALITY_TYPE.QUALITY_BASIC: 		qulIdx = 0; break;
				case QUALITY_TYPE.QUALITY_STANDARD: 	qulIdx = 1; break;
				case QUALITY_TYPE.QUALITY_HIGH: 			qulIdx = 2; break;
				case QUALITY_TYPE.QUALITY_VERY_HIGH: 	qulIdx = 3; break;
			}
			
			switch (framerate) {
				case 1:
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][0]; break;
				case 2:
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][1]; break;
				case 3:
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][2]; break;
				case 4: 
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][3]; break;
				case 5:
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][4]; break;
				case 10:
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][5]; break;
				case 15:
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][6]; break;
				case 30:
					bitrate = real_bitrate[res_cam_idx][resIdx][qulIdx][7]; break;
			}
			camera.current_profiles[profile_index].current_bitrate = bitrate * profile.current_bitrate_ratio * 1000;
			
			if (is_pal)
				camera.current_profiles[profile_index].current_bitrate *= pal_increse_rate;
		}

		bitrate += camera.current_profiles[STREAM_RECORD_TIMELAPS].current_bitrate;
		bitrate += camera.current_profiles[STREAM_RECORD_EVENT].current_bitrate;
	}
	videoRecoder.current_record_bitrate = bitrate;
}
);

