            [0.81, 1.12, 1.43, 1.71, 2.04, 2.14, 2.24, 2.35, 2.45, 2.56, 2.56, 2.56, 2.56], // Quality High
            [1.09, 1.50, 1.90, 2.29, 2.73, 2.86, 3.00, 3.13, 3.26, 3.41, 3.41, 3.41, 3.41]  // Quality Very High    
