        camera.current_profiles[4].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
        camera.current_profiles[2].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
        camera.current_profiles[3].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
    
        camera.current_profiles[0].current_resolution = codecInfo.support_resolution[indexMax].type;
        camera.current_profiles[1].current_resolution = codecInfo.support_resolution[indexMax-1].type;
        camera.current_profiles[4].current_resolution = codecInfo.support_resolution[indexMin+1].type;
        camera.current_profiles[2].current_resolution = codecInfo.support_resolution[indexMax].type;
        camera.current_profiles[3].current_resolution = codecInfo.support_resolution[indexMax].type;           
