        camera.current_profiles[1].current_framerate = parseInt(codecInfo.getResolutionInfo(resolutions[indexMin+1].type).max_framerate);
        camera.current_profiles[4].current_framerate = 5;
        camera.current_profiles[2].current_framerate = parseInt(codecInfo.getResolutionInfo(maxRes).max_framerate);
