vr.setCalculateBitrate(
function func(videoRecoder)
{
	var max_single_bitrate = 0;
    var max_total_live_bitrate = 65*1024;
    var max_total_record_bitrate = 230*1024;
    var max_total_remote_bitrate = 50*1024;
    var total_live1_bitrate = 0;
    var total_live2_bitrate = 0;
    var total_record_bitrate = 0;
    var total_remote_bitrate = 0;
    var DIRECTIP_RES1080_RES_RATIO = [1, 0.75, 0.8, 0.86];
    var record_bitrate = 0;
    
	for (x in videoRecoder.connect_cameras) {
		var camera = videoRecoder.connect_cameras[x];
		var temp_camera = clone(camera);
		var min_bitrate = 0;
		var max_bitrate = 0;
		var bitrate_scale = 0;
		
		temp_camera.calculateBitrate(temp_camera);
        camera.calculateBitrate(camera);
        for (var x in camera.current_profiles)  {
			if (isDirectIP == 2) {
				temp_camera.current_profiles[x].current_quality = QUALITY_TYPE.QUALITY_BASIC;
				temp_camera.calculateBitrate(temp_camera);
				min_bitrate = temp_camera.current_profiles[x].current_bitrate;
				temp_camera.current_profiles[x].current_quality = QUALITY_TYPE.QUALITY_VERY_HIGH;
				temp_camera.calculateBitrate(temp_camera);
				max_bitrate = temp_camera.current_profiles[x].current_bitrate;
				bitrate_scale = (max_bitrate - min_bitrate) / (QUALITY_TYPE.QUALITY_VERY_HIGH - QUALITY_TYPE.QUALITY_BASIC);
				camera.current_profiles[x].current_bitrate = min_bitrate + bitrate_scale * (camera.current_profiles[x].current_quality - QUALITY_TYPE.QUALITY_BASIC);
			}
			if (camera.use_intelligent_codec) {
                camera.current_profiles[x].current_bitrate = camera.current_profiles[x].current_bitrate * camera.intelligent_codec_ratio / 100;
	    	}
	        if (camera.use_wdr) {
			    if (camera.current_profiles[x].current_bitrate > camera.wdr_limit) {
			        camera.current_profiles[x].current_bitrate = camera.wdr_limit;
			    }
			}
            if (camera.use_ssl) {
			    if (camera.current_profiles[x].current_bitrate > camera.ssl_limit) {
			        camera.current_profiles[x].current_bitrate = camera.ssl_limit;
			    }
			}
        }
	    total_live1_bitrate += camera.current_profiles[STREAM_LIVE1].current_bitrate;
	    total_live2_bitrate += camera.current_profiles[STREAM_LIVE2].current_bitrate;
	    total_record_bitrate += camera.current_profiles[STREAM_RECORD_TIMELAPS].current_bitrate;
	    total_record_bitrate += camera.current_profiles[STREAM_RECORD_EVENT].current_bitrate;
	    total_remote_bitrate += camera.current_profiles[STREAM_REMOTE].current_bitrate;
    }
    
	videoRecoder.current_record_bitrate = total_record_bitrate;
}
);

