// cameras는 현재 connect된 camera list이다. 해당 카메라들의 정보를 가지고,
// 현재 video recoder에서 설정가능한 설정 상태인지를 확인하고 수정한다.
// 수정된 카메라의 정보는 UI로 바로 업데이트 된다.
vr.setAdjustCameras(
function func(camera)
{
//NVR별 제약조건 적용
if(document.getElementById("check_direct_ip_mode").checked) {
	var max_total_record_bitrate = 230;
	var max_single_bitrate = 20;
	g_max_total_record_bitrate = max_total_record_bitrate;
	g_max_single_bitrate = max_single_bitrate;
	if (camera.getCodecInfo(CODEC_TYPE.CODEC_H265) != false) {
	    document.getElementById("select_"+STREAM_CONTROL_NAMES[0]+"_resolution").disabled = false;
		document.getElementById("select_"+STREAM_CONTROL_NAMES[0]+"_framerate").disabled = false;

		document.getElementById("select_"+STREAM_CONTROL_NAMES[1]+"_resolution").disabled = false;
		document.getElementById("select_"+STREAM_CONTROL_NAMES[1]+"_framerate").disabled = false;
		return;
	}
	else {
        var res_list = camera.getCodecInfo(camera.current_profiles[0].current_codec).support_resolution;
        var maxResType = res_list[res_list.length-1].type;
        switch(maxResType) {
            case RESOLUTION_TYPE.RES_1280_720:
            case RESOLUTION_TYPE.RES_1920_1080:
				document.getElementById("select_"+STREAM_CONTROL_NAMES[0]+"_framerate").disabled = false;
	            document.getElementById("select_"+STREAM_CONTROL_NAMES[1]+"_framerate").disabled = false;
                break;
            case RESOLUTION_TYPE.RES_2304_1296:
				document.getElementById("select_"+STREAM_CONTROL_NAMES[0]+"_resolution").disabled = false;
				document.getElementById("select_"+STREAM_CONTROL_NAMES[0]+"_framerate").disabled = false;
	            document.getElementById("select_"+STREAM_CONTROL_NAMES[1]+"_framerate").disabled = false;
	            break;
            default :
                document.getElementById("select_"+STREAM_CONTROL_NAMES[0]+"_resolution").disabled = false;
		        document.getElementById("select_"+STREAM_CONTROL_NAMES[0]+"_framerate").disabled = false;

		        document.getElementById("select_"+STREAM_CONTROL_NAMES[1]+"_resolution").disabled = false;
		        document.getElementById("select_"+STREAM_CONTROL_NAMES[1]+"_framerate").disabled = false;
		        break;
	    }
	}
}
else {
    for (var profile in camera.current_profiles) {
        var resolution = camera.current_profiles[profile].current_resolution;
        var framerate = camera.current_profiles[profile].current_framerate;
        var quality = camera.current_profiles[profile].current_quality;
        var res_list = camera.getCodecInfo(camera.current_profiles[profile].current_codec).support_resolution;
        var maxResolution = 0;
        var indexMax = 0;
        for (var x = res_list.length - 1; ; x--)    {
            if (g_current_video_recoder_model.support_resolution_types.indexOf(res_list[x].type) != -1)  {
                indexMax = x;
                maxResolution = res_list[indexMax].type;
                break;
            }
        }
        var maxRes = RESOLUTION_TYPE_STRING[maxResolution].split('x');
        var maxResFactor = Math.round(maxRes[0] * maxRes[1] / 1000000);
        var currentRes = RESOLUTION_TYPE_STRING[resolution].split('x');
        var resFactor = Math.round(currentRes[0] * currentRes[1] / 1000000);
        
        if (maxResFactor < 5) {
            switch(resFactor) {
                case 1:
                case 2:
                    if ((profile ==  2 || profile == 3) && framerate > 15 && quality > QUALITY_TYPE.QUALITY_STANDARD ) {
                        camera.current_profiles[profile].current_framerate = 15;
                    }
                    break;
                case 3:
                    if (RESOLUTION_TYPE_STRING[resolution] == "2048x1536") {
                        if ((profile ==  2 || profile == 3) && framerate > 15 && quality > QUALITY_TYPE.QUALITY_STANDARD ) {
                            camera.current_profiles[profile].current_framerate = 15;
                        }
                        break;
                    }
                case 4:
                    if(framerate > 15) {
                        camera.current_profiles[profile].current_framerate = 15;
                    }
                    break;
                default:
                    break;
            }
        }
        else {
            switch(resFactor) {
                case 5:
                    if (RESOLUTION_TYPE_STRING[resolution] == "2560x2048") {
                        break;
                    }
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                case 11:
                case 12:
                    if(framerate > 15) {
                        camera.current_profiles[profile].current_framerate = 15;
                    }
                    break;
                default:
                    break;
            }
        }
    }
}
}
);

