// videoRecoder는  현재 선택된 recoder오브젝트이다. 해당 카메라 내부의 Profile로 부터
// 개별 birate를 읽어 현재 videorecoder의 current_record_bitrate를 계산한다.
vr.setCalculateBitrate(
function func(videoRecoder)
{
    var bitrate = 0;
    
    for (var x in videoRecoder.connect_cameras) {
        var camera = videoRecoder.connect_cameras[x];

        var codecInfo = camera.getCodecInfo(camera.current_profiles[0].current_codec);
        var maxResolution = codecInfo.support_resolution[codecInfo.support_resolution.length - 1].type;
        var maxRes = RESOLUTION_TYPE_STRING[maxResolution].split('x');
        var maxResFactor = Math.round(maxRes[0] * maxRes[1] / 1000000);
        // RAY계열 및 ROMEO는 성능이슈로 Quality 제약을 갖는다(단, 3M를 초과하는 카메라는 점유 채널수로 제약함).
        var constrain = false;	
        if (maxResFactor < 4) {
            constrain = true;
        }
        var isODM = false;
        if (videoRecoder.name.substring(0, 3) != "DR-") {
            isODM = true;
        }
        if (camera.name == "Custom Camera") {
            camera.calculateBitrate(camera);
            bitrate += camera.current_profiles[STREAM_RECORD_TIMELAPS].current_bitrate;
            bitrate += camera.current_profiles[STREAM_RECORD_EVENT].current_bitrate;            
        }
        else if (constrain && !isODM) {
            camera.calculateBitrate(camera);
            var tmp_camera = clone(camera);
            for (var profile_index in tmp_camera.current_profiles) {
                var currentRes = RESOLUTION_TYPE_STRING[tmp_camera.current_profiles[profile_index].current_resolution].split('x');
                var resFactor = Math.round(currentRes[0] * currentRes[1] / 1000000);
                if (resFactor > 1 && resFactor < 4) {
                    switch (tmp_camera.current_profiles[profile_index].current_quality) {
                        case QUALITY_TYPE.QUALITY_BASIC:
                        case QUALITY_TYPE.QUALITY_STANDARD:
                            tmp_camera.current_profiles[profile_index].current_quality = QUALITY_TYPE.QUALITY_BASIC;
                            break;
                        case QUALITY_TYPE.QUALITY_HIGH:
                            tmp_camera.current_profiles[profile_index].current_quality = QUALITY_TYPE.QUALITY_STANDARD;
                            break;
                        case QUALITY_TYPE.QUALITY_VERY_HIGH:
                            tmp_camera.current_profiles[profile_index].current_quality = QUALITY_TYPE.QUALITY_HIGH;
                            break;
                    }
                    tmp_camera.calculateBitrate(tmp_camera);
                    if (camera.current_profiles[profile_index].current_quality == QUALITY_TYPE.QUALITY_BASIC) {
                        tmp_camera.current_profiles[profile_index].current_bitrate = tmp_camera.current_profiles[profile_index].current_bitrate / 2;
                    }
                }
                camera.current_profiles[profile_index].current_bitrate = tmp_camera.current_profiles[profile_index].current_bitrate;
            }
            
            bitrate += tmp_camera.current_profiles[STREAM_RECORD_TIMELAPS].current_bitrate;
            bitrate += tmp_camera.current_profiles[STREAM_RECORD_EVENT].current_bitrate;
        }
        else if (isODM) {
            camera.calculateBitrate(camera);
            for (var profile_index in camera.current_profiles) {
                if (camera.current_profiles[profile_index].current_resolution == RESOLUTION_TYPE.RES_1920_1080) {
                    switch (camera.current_profiles[profile_index].current_quality) {
                        case QUALITY_TYPE.QUALITY_BASIC:
                            camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate / 2;
                            break;
                        case QUALITY_TYPE.QUALITY_STANDARD:
                            camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate * 5 / 12;
                            break;
                        case QUALITY_TYPE.QUALITY_HIGH:
                            camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate * 3 / 8;
                            break;
                        case QUALITY_TYPE.QUALITY_VERY_HIGH:
                            camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate * 2 / 5;
                            break;
                    }
                }
                else if (camera.current_profiles[profile_index].current_resolution == RESOLUTION_TYPE.RES_1280_720) {
                    switch (camera.current_profiles[profile_index].current_quality) {
                        case QUALITY_TYPE.QUALITY_BASIC:
                            break;
                        case QUALITY_TYPE.QUALITY_STANDARD:
                            camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate * 5 / 8;
                            break;
                        case QUALITY_TYPE.QUALITY_HIGH:
                            camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate / 2;
                            break;
                        case QUALITY_TYPE.QUALITY_VERY_HIGH:
                            camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate / 2;
                            break;
                    }                    
                }
            }
        }
        else {
            camera.calculateBitrate(camera);
            bitrate += camera.current_profiles[STREAM_RECORD_TIMELAPS].current_bitrate;
            bitrate += camera.current_profiles[STREAM_RECORD_EVENT].current_bitrate;
        }
        for (var profile_index in camera.current_profiles) {
            if (camera.use_intelligent_codec) {
				camera.current_profiles[profile_index].current_bitrate = camera.current_profiles[profile_index].current_bitrate * camera.intelligent_codec_ratio / 100;
	    	}
            if (camera.use_wdr) {
    		    if (camera.current_profiles[profile_index].current_bitrate > camera.wdr_limit) {
    		        camera.current_profiles[profile_index].current_bitrate = camera.wdr_limit;
    		    }
    		}
            if (camera.use_ssl) {
    		    if (camera.current_profiles[profile_index].current_bitrate > camera.ssl_limit) {
    		        camera.current_profiles[profile_index].current_bitrate = camera.ssl_limit;
    		    }
    		}
    	}
    }
    videoRecoder.current_record_bitrate = bitrate;
    console.log("[" + videoRecoder.name + "] setCalculateBitrate(), bitrate = " + bitrate);
    
}
);

// 해상도를 입력받아 카메라슬롯 가중치를 계산한다.
