vr.setCalculateCameraSlot(
function func(Resolution, ips)
{
    if (Resolution < 5) {
        return 1;
    }
    else if (Resolution == 5) {
        return 2;
    }
    else if (Resolution == 8 ) {
        return 4;
    }
    else if (Resolution > 8 ) {
        return 8;
    }
    else {
        return 1;
    }
}
);
