    // UI 업데이트 로직
    vr.setAdjustCameras(function func(camera) {

    var max_total_record_bitrate = 90;
	var max_single_bitrate = 20;
    g_max_total_record_bitrate = max_total_record_bitrate;
	g_max_single_bitrate = max_single_bitrate;

        if (camera.type == VIDEO_CAMERA_TYPE.ANALOG) {
        adjustHybridAnalogCamera(camera);
        }

    else{
        adjustHybridNetworkCamera(camera);
        }
    });

    // 기본값 설정
    vr.setAdjustDefaultSettings(function func(camera) {
        if (camera.type == VIDEO_CAMERA_TYPE.ANALOG) {
        adjustHybridAnalogDefault(camera);
        } 
        else {
        adjustHybridNetworkDefault(camera);
        }
        
    });

